// The armour explainer (assets/armour.html, shown from the builder's gear step): its figures read from the game's code
// (coverage.js, physics.js protectionAt, outfits.js ARMOUR_METALS), set into tools/armour-page.tpl.html.
// GENERATED page: do not edit assets/armour.html by hand; edit the template and run: node tools/armour-page.mjs
import { readFileSync, writeFileSync } from 'node:fs';
const root = new URL('..', import.meta.url).pathname.replace(/\/$/, '');
const { buildBody, normaliseInputs, PRESETS } = await import(`${root}/src/body.js`);
const { protectionAt } = await import(`${root}/src/physics.js`);
const { OUTFITS, ARMOUR_METALS } = await import(`${root}/src/outfits.js`);
const { coverageOf, ARMOUR_COVER } = await import(`${root}/src/coverage.js`);
const { punctureOf, edgeProofOf } = await import(`${root}/src/weapons.js`);
const KITS = [['knight', 0], ['samuraiTosei', 0], ['mingBrigandine', 0], ['bayara', 0], ['conquistadorPlate', 0], ['ashigaru', 0]];
const PARTS = [['trunk', 'trunk'], ['upperArm', 'lUpperArm'], ['forearm', 'lForearm'], ['thigh', 'lThigh'], ['shank', 'lShank']];
const N = 24;
const r3 = (v) => Math.round((v ?? 0) * 1000) / 1000;
const kits = KITS.map(([kind, design]) => {
  const gear = buildBody(normaliseInputs({ ...structuredClone(PRESETS.contender), outfit: { kind, design }, accessories: [] })).gear;
  const cover = coverageOf(gear.cover.armor, gear.cover);
  const parts = {};
  for (const [name, key] of PARTS) {
    parts[name] = Array.from({ length: N }, (_, i) => { const t = (i + 0.5) / N; const p = protectionAt(gear, key, t); return [r3(p.cut), r3(p.pierce), r3(p.blunt)]; });
  }
  const head = protectionAt(gear, 'head');
  return { kind, label: OUTFITS[kind].designs[design].label ?? OUTFITS[kind].label, kitLabel: OUTFITS[kind].label, metal: gear.metal, head: [r3(head.cut), r3(head.pierce), r3(head.blunt)], parts,
    pieces: Object.fromEntries(Object.entries(cover).filter(([, v]) => Array.isArray(v)).map(([k, v]) => [k, v.map((p) => ({ from: r3(p.from), to: r3(p.to), material: p.material, slot: p.slot }))])), hand: cover.hand, foot: cover.foot };
});
// The worked example: a spear's thrust (a 2 cm bodkin-like point) at the conquistador's upper arm and forearm.
const ex = (kind, key, t) => { const gear = buildBody(normaliseInputs({ ...structuredClone(PRESETS.contender), outfit: { kind, design: 0 }, accessories: [] })).gear; const p = protectionAt(gear, key, t); return { cut: r3(p.cut), pierce: r3(p.pierce), blunt: r3(p.blunt), puncture: Math.round(punctureOf(p.pierce)), edge: Math.round(edgeProofOf(p.cut)) }; };
const examples = {
  conqUpper: ex('conquistadorPlate', 'lUpperArm', 0.5), conqFore: ex('conquistadorPlate', 'lForearm', 0.5), conqBelly: ex('conquistadorPlate', 'trunk', 0.05), conqChest: ex('conquistadorPlate', 'trunk', 0.6),
  knightChest: ex('knight', 'trunk', 0.6), toseiKnee: ex('samuraiTosei', 'lThigh', 0.93), toseiShin: ex('samuraiTosei', 'lShank', 0.5), toseiHand: ex('samuraiTosei', 'lForearm', 0.95),
};
const metals = Object.entries(ARMOUR_METALS).map(([k, m]) => ({ key: k, proof: m.proof, vph: m.vph }));
// The same breastplate figures (iron: cut 0.9, pierce 0.85) in each metal.
const { cutOfEdgeProof, pierceOfPuncture } = await import(`${root}/src/weapons.js`);
for (const m of metals) { m.cut = r3(Math.min(1, cutOfEdgeProof(edgeProofOf(0.9) * m.proof))); m.pierce = r3(pierceOfPuncture(punctureOf(0.85) * m.proof)); }
const data = { kits, examples, metals, handFrom: ARMOUR_COVER.handFrom, footFrom: ARMOUR_COVER.footFrom, when: new Date().toISOString().slice(0, 10) };
const page = readFileSync(`${root}/tools/armour-page.tpl.html`, 'utf8').replace('/*DATA*/null', JSON.stringify(data));
writeFileSync(`${root}/assets/armour.html`, `<!doctype html>\n<!-- GENERATED by tools/armour-page.mjs from tools/armour-page.tpl.html: do not edit by hand. -->\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n</head>\n<body>\n${page}\n</body>\n</html>\n`);
if (process.argv[2]) writeFileSync(process.argv[2], page);
console.log('wrote assets/armour.html', Math.round(page.length / 1024), 'KB');
